declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';if(is_file(__DIR__.'/../app/access_control_v1300.php'))require_once __DIR__.'/../app/access_control_v1300.php';require_once __DIR__.'/../app/services_v1380.php';$p=sk1380_require_provider();$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{sk1380_csrf_check();$pkg=(int)$_POST['package_id'];$q=sk1380_db()->prepare('SELECT * FROM service_packages_v1380 WHERE tenant_id=? AND id=? AND active=1');$q->execute([sk1380_tid(),$pkg]);$x=$q->fetch(PDO::FETCH_ASSOC);if(!$x)throw new RuntimeException('Package not available.');if((float)$x['price']<=0)throw new RuntimeException('This package does not require a paid request. Ask admin to assign it if applicable.');$ref=trim((string)($_POST['payment_reference']??''));if($ref==='')throw new RuntimeException('Payment/reference number is required for admin verification.');sk1380_db()->prepare('INSERT INTO service_package_orders_v1380(tenant_id,provider_id,package_id,amount_snapshot,payment_reference,payment_note,status,created_at,updated_at) VALUES(?,?,?,?,?,?,"pending",NOW(),NOW())')->execute([sk1380_tid(),$p['id'],$pkg,$x['price'],$ref,trim((string)($_POST['payment_note']??''))?:null]);$msg='Package request submitted. Admin will activate it after payment verification.';}catch(Throwable $e){$err=$e->getMessage();}}$q=sk1380_db()->prepare('SELECT * FROM service_packages_v1380 WHERE tenant_id=? AND active=1 ORDER BY sort_order,id');$q->execute([sk1380_tid()]);$pkgs=$q->fetchAll(PDO::FETCH_ASSOC)?:[];$q=sk1380_db()->prepare('SELECT po.*,pk.name FROM service_package_orders_v1380 po JOIN service_packages_v1380 pk ON pk.id=po.package_id WHERE po.tenant_id=? AND po.provider_id=? ORDER BY po.id DESC LIMIT 20');$q->execute([sk1380_tid(),$p['id']]);$orders=$q->fetchAll(PDO::FETCH_ASSOC)?:[];sk1380_shell('Provider Packages','packages');?><section class="dash-hero"><div><span class="eyebrow">PROVIDER PACKAGES</span><h1>Grow your local service business</h1><p>Paid benefits only activate after admin verifies the payment/reference. No automatic payment success is assumed.</p></div><a href="/provider/services.php">Dashboard</a></section><?php if($msg):?><div class="notice ok"><?=sk1380_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice err"><?=sk1380_h($err)?></div><?php endif;?><div class="package-grid"><?php foreach($pkgs as $pk):$e=json_decode($pk['entitlements_json'],true)?:[];?><article><span><?=sk1380_h($pk['name'])?></span><h2><?=$pk['price']>0?'PKR '.number_format((float)$pk['price'],0):'Free / Admin'?></h2><p><?=sk1380_h($pk['description'])?></p><ul><li><?=number_format((int)($e['service_limit']??0))?> service listings</li><li><?=number_format((int)($e['monthly_quote_limit']??0))?> quotes / month</li><li><?=$e['fast_service']?'Fast Service enabled':'Standard response mode'?></li><li><?=number_format((int)($e['featured_slots']??0))?> featured slots</li><li>Search priority +<?=number_format((int)($e['priority_weight']??0))?></li></ul><?php if($pk['price']>0):?><form method="post"><input type="hidden" name="_csrf" value="<?=sk1380_h(sk1380_csrf())?>"><input type="hidden" name="package_id" value="<?=$pk['id']?>"><input name="payment_reference" required placeholder="Payment / transaction reference"><input name="payment_note" placeholder="Optional payment note"><button>Submit for Admin Approval</button></form><?php endif;?></article><?php endforeach;?></div><h2>Package Requests</h2><div class="simple-table"><?php foreach($orders as $o):?><div><b><?=sk1380_h($o['name'])?></b><span><?=sk1380_h($o['payment_reference'])?></span><strong><?=sk1380_h(strtoupper($o['status']))?></strong></div><?php endforeach;?></div><?php sk1380_end();